// Shader de píxeles en GLSL: se ejecuta una vez por cada píxel
uniform sampler2D foto;   // la imagen de entrada
in vec2 uv;               // posición de este píxel en la imagen
out vec4 salida;          // el color que va a la pantalla

void main() {
    vec3 c = texture(foto, uv).rgb;                 // color original (R, G, B)
    float gris = dot(c, vec3(0.299, 0.587, 0.114)); // promedio ponderado
    salida = vec4(vec3(gris), 1.0);                 // R = G = B = gris
}

// Un píxel = [R, G, B] de 0 a 255
const gris = ([r, g, b]) => {
  const y = Math.round(0.299 * r + 0.587 * g + 0.114 * b);
  return [y, y, y];
};

const pixeles = [[255,0,0],[0,255,0],[0,0,255],[255,255,255],[10,20,30],[200,150,100]];
const salida = pixeles.map(gris);   // la GPU hace esto en miles de unidades a la vez

pixeles.forEach((p, i) => console.log(`[${p}] -> [${salida[i]}]`));

const fullHD = 1920 * 1080;
console.log(`Un cuadro Full HD son ${fullHD.toLocaleString('es-AR')} llamadas a esta función.`);
console.log(`A 60 cuadros por segundo: ${(fullHD * 60).toLocaleString('es-AR')} llamadas por segundo.`);
